<script setup>
import { computed, onMounted, ref } from 'vue'
import { api, errorMessage } from '../api'
const discounts=ref([]), products=ref([]), q=ref(''), error=ref(''), success=ref(''), saving=ref(false), editingId=ref(null)
const emptyForm=()=>({variantId:'',salesChannel:'BOTH',discountType:'PERCENT',discountValue:10,startsAt:'',endsAt:'',reason:''})
const form=ref(emptyForm())
const variants=computed(()=>products.value.flatMap(p=>(p.variants||[]).map(v=>({id:v.id,label:`${p.name} · ${v.sku} · ${v.size||'Size chuẩn'} ${v.color||'Màu chuẩn'}`}))))
function dateInput(value){return value?String(value).slice(0,16):''}
function body(){return {variantId:Number(form.value.variantId),salesChannel:form.value.salesChannel,discountType:form.value.discountType,discountValue:Number(form.value.discountValue),startsAt:form.value.startsAt||null,endsAt:form.value.endsAt||null,reason:form.value.reason,active:true}}
async function load(){error.value='';try{const [d,p]=await Promise.all([api.get('/api/admin/variant-discounts',{params:{q:q.value}}),api.get('/api/admin/products')]);discounts.value=d.data;products.value=p.data}catch(e){error.value=errorMessage(e)}}
function edit(d){editingId.value=d.id;form.value={variantId:String(d.variantId),salesChannel:d.channel,discountType:d.type,discountValue:d.value,startsAt:dateInput(d.startsAt),endsAt:dateInput(d.endsAt),reason:d.reason||''};document.querySelector('.variant-discount-editor')?.scrollIntoView({behavior:'smooth',block:'start'})}
function reset(){editingId.value=null;form.value=emptyForm()}
async function save(){saving.value=true;error.value='';success.value='';try{const p=body();if(editingId.value){await api.patch(`/api/admin/variant-discounts/${editingId.value}`,p);success.value='Đã cập nhật giảm giá biến thể.'}else{await api.post('/api/admin/variant-discounts',p);success.value='Đã tạo ưu đãi biến thể.'}reset();await load()}catch(e){error.value=errorMessage(e)}finally{saving.value=false}}
async function toggle(d){try{await api.patch(`/api/admin/variant-discounts/${d.id}`,{variantId:d.variantId,salesChannel:d.channel,discountType:d.type,discountValue:Number(d.value),startsAt:d.startsAt||null,endsAt:d.endsAt||null,reason:d.reason,active:!d.active});success.value=d.active?'Đã chuyển ưu đãi sang Dừng.':'Đã chuyển ưu đãi sang Hoạt động.';await load()}catch(e){error.value=errorMessage(e)}}
async function remove(d){if(!confirm(`Xóa vĩnh viễn ưu đãi biến thể cho SKU ${d.sku}?`))return;try{await api.delete(`/api/admin/variant-discounts/${d.id}`);success.value='Đã xóa ưu đãi biến thể.';await load()}catch(e){error.value=errorMessage(e)}}
</script>
<template>
  <div class="view-wrap"><div class="view-heading"><div><span class="eyebrow">SALES / VARIANT DISCOUNTS</span><h1>Giảm giá biến thể</h1><p>Giảm giá theo SKU/size/màu và kênh ONLINE, OFFLINE hoặc BOTH. Khi nhiều ưu đãi hợp lệ cùng áp dụng, ưu tiên ưu đãi biến thể được tạo mới nhất.</p></div><button class="btn btn-outline" @click="load">Làm mới</button></div>
    <p v-if="error" class="notice notice-error">{{error}}</p><p v-if="success" class="notice notice-success">{{success}}</p>
    <section class="surface-card variant-discount-editor"><div class="section-toolbar"><div><span class="eyebrow">{{editingId?'UPDATE DISCOUNT':'CREATE DISCOUNT'}}</span><h2>{{editingId?`Chỉnh sửa ưu đãi #${editingId}`:'Tạo ưu đãi mặt hàng'}}</h2></div><button v-if="editingId" class="btn btn-outline btn-sm" @click="reset">Hủy sửa</button></div>
      <form class="coupon-form-grid" @submit.prevent="save"><label class="wide-field">Biến thể / SKU<select v-model="form.variantId" required><option value="" disabled>Chọn biến thể sản phẩm</option><option v-for="v in variants" :key="v.id" :value="v.id">{{v.label}}</option></select></label><label>Kênh áp dụng<select v-model="form.salesChannel"><option value="BOTH">Cả Online và Offline</option><option value="ONLINE">Online</option><option value="OFFLINE">Offline / POS</option></select></label><label>Loại giảm<select v-model="form.discountType"><option value="PERCENT">Phần trăm (%)</option><option value="AMOUNT">Số tiền / đôi (₫)</option></select></label><label>Giá trị giảm<input v-model="form.discountValue" type="number" min="1" required/></label><label>Bắt đầu<input v-model="form.startsAt" type="datetime-local"/></label><label>Kết thúc<input v-model="form.endsAt" type="datetime-local"/></label><label class="wide-field">Lý do<input v-model="form.reason" placeholder="Khuyến mãi cuối tuần…"/></label><button class="btn btn-primary" :disabled="saving">{{saving?'Đang lưu…':(editingId?'Lưu thay đổi':'Tạo ưu đãi')}}</button></form>
    </section>
    <section class="surface-card"><div class="section-toolbar"><div><h2>Danh sách ưu đãi</h2><small class="muted">{{discounts.length}} ưu đãi phù hợp</small></div><div class="search-tools"><input v-model="q" @keyup.enter="load" placeholder="Tìm tên sản phẩm / SKU…"/><button class="btn btn-outline btn-sm" @click="load">Tìm kiếm</button></div></div>
      <div v-for="d in discounts" :key="d.id" class="coupon-admin-card"><div><b>{{d.productName}}</b><small>SKU {{d.sku}} · {{d.channel}} · {{d.type==='PERCENT'?`${d.value}%`:`${Number(d.value).toLocaleString('vi-VN')}₫`}}</small><small>{{d.reason||'Không có ghi chú'}} · {{d.startsAt||'Ngay lập tức'}} → {{d.endsAt||'Không giới hạn'}}</small></div><div class="coupon-card-actions"><span :class="d.active?'text-success':'muted'">{{d.active?'Hoạt động':'Dừng'}}</span><button class="btn btn-outline btn-sm" @click="edit(d)">Sửa</button><button class="btn btn-outline btn-sm" @click="toggle(d)">{{d.active?'Dừng':'Hoạt động'}}</button><button class="btn btn-danger-outline btn-sm" @click="remove(d)">Xóa</button></div></div><div v-if="!discounts.length" class="empty-state">Chưa có ưu đãi biến thể.</div>
    </section>
  </div>
</template>
